<script setup>
import {router} from '@inertiajs/vue3';import PortalLayout from '@/Layouts/PortalLayout.vue'
const props=defineProps({doctor:Object,clinics:Array,filters:Object,report:Object})
const n=v=>new Intl.NumberFormat('fa-IR').format(Number(v||0)),pct=v=>v==null?'—':n(v)+'٪',money=v=>n(v)+' ریال'
const apply=e=>router.get(route('portal.clinic-performance.index'),Object.fromEntries(new FormData(e.target).entries()),{preserveState:true,preserveScroll:true})
const max=Math.max(1,...props.report.daily.map(x=>x.total))
</script>
<template><PortalLayout :doctor="doctor" title="عملکرد کلینیک"><main dir="rtl" class="mx-auto max-w-7xl space-y-5 p-3 sm:p-5">
<header class="rounded-3xl bg-gradient-to-l from-slate-950 to-teal-800 p-6 text-white"><p class="text-xs font-bold text-teal-200">PRONEEX · CLINIC PERFORMANCE</p><h1 class="mt-2 text-2xl font-black">مرکز سنجش عملکرد کلینیک</h1><p class="mt-2 text-sm text-white/80">شاخص‌های تجمیعی بهره‌وری، ظرفیت، مراجعات و دریافت‌های موفق.</p></header>
<form @submit.prevent="apply" class="grid gap-3 rounded-2xl border bg-white p-4 sm:grid-cols-4"><label class="text-xs">از تاریخ<input name="from" type="date" :value="filters.from" class="mt-1 w-full rounded-xl border-slate-300"></label><label class="text-xs">تا تاریخ<input name="to" type="date" :value="filters.to" class="mt-1 w-full rounded-xl border-slate-300"></label><label class="text-xs">شعبه<select name="clinic_id" :value="filters.clinic_id||''" class="mt-1 w-full rounded-xl border-slate-300"><option value="">همه شعب مجاز</option><option v-for="c in clinics" :key="c.id" :value="c.id">{{c.name}}</option></select></label><button class="self-end rounded-xl bg-teal-700 px-4 py-2.5 text-sm font-bold text-white">اعمال فیلتر</button></form>
<section class="grid grid-cols-2 gap-3 xl:grid-cols-4"><article class="rounded-2xl border bg-white p-4"><span class="text-xs text-slate-500">کل نوبت‌ها</span><b class="mt-2 block text-2xl">{{n(report.appointments.total)}}</b></article><article class="rounded-2xl border bg-white p-4"><span class="text-xs text-slate-500">نرخ انجام مراجعه</span><b class="mt-2 block text-2xl text-emerald-700">{{pct(report.appointments.completion_rate)}}</b><p class="text-xs text-slate-500">{{n(report.appointments.served)}} انجام‌شده</p></article><article class="rounded-2xl border bg-white p-4"><span class="text-xs text-slate-500">نرخ لغو</span><b class="mt-2 block text-2xl text-amber-700">{{pct(report.appointments.cancellation_rate)}}</b><p class="text-xs text-slate-500">{{n(report.appointments.cancelled)}} لغوشده</p></article><article class="rounded-2xl border bg-white p-4"><span class="text-xs text-slate-500">دریافت موفق ناخالص</span><b class="mt-2 block text-xl text-teal-700">{{money(report.finance.gross_paid_rial)}}</b><p class="text-xs text-slate-500">{{n(report.finance.paid_appointments)}} پرداخت</p></article></section>
<section class="grid gap-3 lg:grid-cols-2"><article class="rounded-2xl border bg-white p-4"><h2 class="font-black">ظرفیت نوبت‌دهی</h2><b class="mt-3 block text-3xl">{{pct(report.capacity.rate)}}</b><div class="mt-3 h-3 overflow-hidden rounded-full bg-slate-100"><div class="h-full bg-teal-600" :style="{width:(report.capacity.rate||0)+'%'}"></div></div><p class="mt-2 text-xs text-slate-500">{{n(report.capacity.occupied)}} اشغال از {{n(report.capacity.total)}} · {{n(report.capacity.available)}} آزاد</p></article><article class="rounded-2xl border bg-white p-4"><h2 class="font-black">وضعیت نوبت‌ها</h2><div class="mt-4 grid grid-cols-2 gap-2 text-center sm:grid-cols-5"><div class="rounded-xl bg-emerald-50 p-3"><b>{{n(report.appointments.served)}}</b><p class="text-xs">انجام‌شده</p></div><div class="rounded-xl bg-sky-50 p-3"><b>{{n(report.appointments.confirmed)}}</b><p class="text-xs">تأییدشده</p></div><div class="rounded-xl bg-indigo-50 p-3"><b>{{n(report.appointments.contacted)}}</b><p class="text-xs">تماس‌گرفته‌شده</p></div><div class="rounded-xl bg-amber-50 p-3"><b>{{n(report.appointments.pending)}}</b><p class="text-xs">در انتظار</p></div><div class="rounded-xl bg-rose-50 p-3"><b>{{n(report.appointments.cancelled)}}</b><p class="text-xs">لغو</p></div></div></article></section>
<section class="rounded-2xl border bg-white p-4"><h2 class="font-black">روند روزانه نوبت‌ها</h2><div v-if="report.daily.length" class="mt-4 flex min-h-44 items-end gap-1 overflow-x-auto border-b pb-2"><div v-for="x in report.daily" :key="x.day" class="flex min-w-7 flex-1 flex-col items-center justify-end gap-1"><span class="text-[9px]">{{n(x.total)}}</span><div class="w-full rounded-t bg-teal-600" :style="{height:Math.max(4,x.total/max*120)+'px'}"></div><span class="text-[9px] text-slate-400">{{x.day.slice(5)}}</span></div></div><p v-else class="py-8 text-center text-xs text-slate-500">داده‌ای وجود ندارد.</p></section>
<section class="rounded-2xl border bg-white p-4"><h2 class="font-black">مقایسه شعب</h2><div class="mt-3 overflow-x-auto"><table class="w-full min-w-[560px] text-right text-xs"><thead class="bg-slate-50"><tr><th class="p-3">شعبه</th><th class="p-3">نوبت</th><th class="p-3">انجام</th><th class="p-3">لغو</th><th class="p-3">انتظار</th><th class="p-3">نرخ تکمیل</th><th class="p-3">ظرفیت اشغال</th><th class="p-3">دریافت موفق</th></tr></thead><tbody><tr v-for="c in report.clinics" :key="c.id" class="border-t"><td class="p-3 font-bold">{{c.name}}</td><td class="p-3">{{n(c.appointments)}}</td><td class="p-3">{{n(c.served)}}</td><td class="p-3">{{n(c.cancelled)}}</td><td class="p-3">{{n(c.awaiting)}}</td><td class="p-3">{{pct(c.completion_rate)}}</td><td class="p-3">{{pct(c.capacity_rate)}} ({{n(c.capacity_occupied)}}/{{n(c.capacity_total)}})</td><td class="p-3">{{money(c.gross_paid_rial)}}</td></tr></tbody></table></div></section>
<section class="rounded-2xl border border-amber-200 bg-amber-50 p-4"><h2 class="font-black text-amber-950">محدودیت شاخص‌ها</h2><ul class="mt-2 list-disc space-y-1 pr-5 text-xs leading-6 text-amber-900"><li v-for="x in report.notes" :key="x">{{x}}</li></ul><p class="mt-2 text-xs">این گزارش برای رتبه‌بندی علمی یا ارزیابی کیفیت درمان پزشکان طراحی نشده است.</p></section>
</main></PortalLayout></template>